{"tool": "write_file", "args": {"content": """"One-time verification for LIFE-203: check the registry after merging duplicates."""

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

from core.ids import is_valid_household_id  # noqa: E402
from registry.register import load_households  # noqa: E402


def main() -> None:
    households = load_households(active_only=False)
    ids = [h.id for h in households]
    assert len(ids) == len(set(ids)), "duplicate household IDs"

    active = {}
    for h in households:
        if h.status == "active":
            key = (h.members[0].name, h.members[0].birth_year)
            active.setdefault(key, []).append(h.id)
    dupes = {k: v for k, v in active.items() if len(v) > 1}
    assert not dupes, f"families with more than one active record: {dupes}"

    for h in households:
        if h.status == "active":
            assert is_valid_household_id(h.id), f"active record {h.id} has invalid ID"
        if h.status == "merged":
            assert h.merged_into, f"merged record {h.id} has no merged_into"

    print(f"ok: {len(households)} records, {len(active)} active families, all checks passed")


if __name__ == "__main__":
    main()
